import {
  useMemo,
  useState,
} from "react";

import {
  Box,
  Button,
  Stack,
  Typography,
} from "@mui/material";

import {
  AirRounded,
  CloudRounded,
  OpacityRounded,
  ThermostatRounded,
  UmbrellaRounded,
  WbSunnyRounded,
  WaterDropRounded,
} from "@mui/icons-material";

import CardFilterDropdown, {
  CardFilterConfig,
  FilterOption,
} from "../../../components/common/CardFilterDropdown";

import { useForecastContext } from "../../../contexts/ForecastContext";

import {
  useWeatherOutlook,
  useWeatherSignals,
  useWeatherSummary,
} from "../hooks/useWeather";

import {
  WeatherOutlookDay,
} from "../types/weather.types";


interface WeatherIntelligenceProps {
  entityId: string;
}


type WeatherView =
  | "current"
  | "7"
  | "30";


const WeatherIntelligence = ({
  entityId: propEntityId,
}: WeatherIntelligenceProps) => {
  const {
    horizon,
    setHorizon,
    metric,
    setMetric,
    entityId: contextEntityId,
    setEntityId,
    scenario,
    setScenario,
    forecastEntities,
  } = useForecastContext();

  // Use prop entityId if provided, otherwise use context
  const entityId = propEntityId || contextEntityId;

  const [
    view,
    setView,
  ] = useState<WeatherView>(
    "current"
  );

  // Filter options
  const horizonOptions: FilterOption[] = [
    { label: "Daily", value: "daily" },
    { label: "Monthly", value: "monthly" },
  ];

  const metricOptions: FilterOption[] = [
    { label: "Burn", value: "burn" },
    { label: "Supply", value: "supply" },
    { label: "Stockpile", value: "stockpile" },
  ];

  const stationOptions: FilterOption[] = forecastEntities.map((entity) => ({
    label: entity.name,
    value: entity.id,
  }));

  const scenarioOptions: FilterOption[] = [
    { label: "Baseline", value: "actual" },
    { label: "Hot & Dry", value: "hotdry" },
    { label: "Hot & Wet", value: "hotwet" },
    { label: "Cold & Dry", value: "colddry" },
    { label: "Cold & Wet", value: "coldwet" },
  ];

  const filterConfig: CardFilterConfig = {
    horizon: {
      value: horizon,
      onChange: setHorizon,
      options: horizonOptions,
    },
    metric: {
      value: metric,
      onChange: setMetric,
      options: metricOptions,
    },
    station: {
      value: entityId,
      onChange: setEntityId,
      options: stationOptions,
    },
    scenario: {
      value: scenario,
      onChange: setScenario,
      options: scenarioOptions,
    },
  };


  const days =
    view === "30"
      ? 30
      : 7;


  const {
    data: current,
    isLoading:
    currentLoading,
    isError:
    currentError,
  } =
    useWeatherSummary(
      entityId
    );


  const {
    data: outlook = [],
    isLoading:
    outlookLoading,
    isError:
    outlookError,
  } =
    useWeatherOutlook(
      entityId,
      days
    );


  const {
    data: signals,
    isLoading:
    signalsLoading,
  } =
    useWeatherSignals(
      entityId,
      days
    );


  const formatNumber = (
    value:
      | number
      | null
      | undefined,
    decimals = 1
  ) => {
    if (
      value === null ||
      value === undefined
    ) {
      return "—";
    }

    return value.toFixed(
      decimals
    );
  };


  const formatDate = (
    date: string
  ) => {
    const parsed =
      new Date(date);

    if (
      Number.isNaN(
        parsed.getTime()
      )
    ) {
      return date;
    }

    return parsed.toLocaleDateString(
      "en-GB",
      {
        day: "2-digit",
        month: "short",
      }
    );
  };


  const getDayName = (
    date: string
  ) => {
    const parsed =
      new Date(date);

    if (
      Number.isNaN(
        parsed.getTime()
      )
    ) {
      return "";
    }

    return parsed.toLocaleDateString(
      "en-US",
      {
        weekday: "short",
      }
    );
  };


  const getWeatherIcon = (
    condition:
      | string
      | null
      | undefined
  ) => {
    const text =
      (
        condition ?? ""
      ).toLowerCase();

    if (
      text.includes("rain") ||
      text.includes("shower") ||
      text.includes("drizzle")
    ) {
      return (
        <UmbrellaRounded />
      );
    }

    if (
      text.includes("cloud") ||
      text.includes("overcast")
    ) {
      return (
        <CloudRounded />
      );
    }

    if (
      text.includes("sun") ||
      text.includes("clear")
    ) {
      return (
        <WbSunnyRounded />
      );
    }

    return (
      <CloudRounded />
    );
  };


  const currentTemperature =
    useMemo(() => {
      if (!current) {
        return null;
      }

      return (
        current.tempMax ??
        current.tempMin
      );
    }, [current]);


  const loading =
    currentLoading ||
    outlookLoading ||
    signalsLoading;


  const error =
    currentError ||
    outlookError;


  return (
    <Box
      sx={{
        width: "100%",
        height: "100%",
        bgcolor: "background.paper",
        border: "1px solid",
        borderColor: "divider",
        borderRadius: "12px !important",
        p: { xs: 2.5, md: 3 },
        boxSizing: "border-box",
        overflow: "auto",
        maxHeight: { xs: "auto", xl: "900px" },
        boxShadow: (t) =>
          t.palette.mode === "dark"
            ? "0 10px 30px rgba(0,0,0,0.4)"
            : "0 10px 30px rgba(16,32,62,0.06)",
      }}
    >
      {/* HEADER */}

      <Stack
        direction="column"
        spacing={2}
        alignItems="flex-start"
        sx={{ minWidth: 0, overflow: "hidden", mb: 2 }}
      >
        <Stack
          direction={{ xs: "column", sm: "row" }}
          spacing={2}
          alignItems={{ xs: "flex-start", sm: "center" }}
          sx={{ width: "100%" }}
        >
          <Box
            sx={{
              width: 48,
              height: 48,
              borderRadius: 2,
              bgcolor:
                "#EEF4FF",
              color:
                "#1264FF",
              display: "flex",
              alignItems:
                "center",
              justifyContent:
                "center",
              flexShrink: 0,
            }}
          >
            <CloudRounded
              sx={{
                fontSize: 28,
              }}
            />
          </Box>

          <Box sx={{ minWidth: 0, flex: 1 }}>
            <Typography
              variant="h6"
              fontWeight={800}
              color="text.primary"
            >
              Weather Intelligence
            </Typography>

            <Typography
              variant="body2"
              color="text.secondary"
              mt={0.5}
              sx={{
                wordBreak: "break-word",
                overflowWrap: "break-word",
              }}
            >
              Conditions and outlook for{" "}
              <strong>
                {entityId}
              </strong>
            </Typography>
          </Box>
        </Stack>


        {/* VIEW TOGGLE */}

        <ButtonGroup
          variant="outlined"
          size="small"
          sx={{
            flexShrink: 0,
            width: { xs: "100%", sm: "auto" },
            gap: 1,
            "& .MuiButton-root": {
              textTransform:
                "none",
              fontWeight: 700,
              minWidth: {
                xs: "auto",
                sm: 85,
              },
              flex: { xs: 1, sm: "0 0 auto" },
              marginLeft: "0 !important",
              border: "1px solid",
              borderColor: "divider",
              borderRadius: "8px !important",
            },
          }}
        >
          <Button
            onClick={() =>
              setView("current")
            }
            variant={
              view === "current"
                ? "contained"
                : "outlined"
            }
          >
            Current
          </Button>

          <Button
            onClick={() =>
              setView("7")
            }
            variant={
              view === "7"
                ? "contained"
                : "outlined"
            }
          >
            7 Days
          </Button>

          <Button
            onClick={() =>
              setView("30")
            }
            variant={
              view === "30"
                ? "contained"
                : "outlined"
            }
          >
            30 Days
          </Button>
        </ButtonGroup>
      </Stack>


      <Divider
        sx={{
          my: 2,
        }}
      />


      {/* CURRENT VIEW */}

      {view === "current" && (
        <CurrentWeather
          current={current}
          temperature={
            currentTemperature
          }
          loading={
            currentLoading
          }
          error={
            currentError
          }
          formatNumber={
            formatNumber
          }
          formatDate={
            formatDate
          }
          getWeatherIcon={
            getWeatherIcon
          }
        />
      )}


      {/* OUTLOOK VIEW */}

      {view !== "current" && (
        <>
          {error ? (
            <Typography
              color="error"
              py={4}
            >
              Unable to load the
              weather outlook.
            </Typography>
          ) : loading ? (
            <Typography
              color="text.secondary"
              py={4}
            >
              Loading weather outlook...
            </Typography>
          ) : (
            <>
              <WeatherOutlookGrid
                records={outlook}
                formatNumber={
                  formatNumber
                }
                formatDate={
                  formatDate
                }
                getDayName={
                  getDayName
                }
                getWeatherIcon={
                  getWeatherIcon
                }
              />

              <WeatherSignals
                signals={signals}
                formatNumber={
                  formatNumber
                }
              />
            </>
          )}
        </>
      )}
    </Box>
  );
};


/* =========================================================
   CURRENT WEATHER
========================================================= */


interface CurrentWeatherProps {
  current:
  | {
    condition: string;
    tempMax:
    | number
    | null;
    tempMin:
    | number
    | null;
    rainfall:
    | number
    | null;
    cloudCover:
    | number
    | null;
    humidity:
    | number
    | null;
    windSpeed:
    | number
    | null;
    uvIndex:
    | number
    | null;
    sunshine:
    | number
    | null;
    date: string;
  }
  | null
  | undefined;

  temperature:
  | number
  | null;

  loading: boolean;

  error: boolean;

  formatNumber: (
    value:
      | number
      | null
      | undefined,
    decimals?: number
  ) => string;

  formatDate: (
    value: string
  ) => string;

  getWeatherIcon: (
    condition:
      | string
      | null
      | undefined
  ) => React.ReactNode;
}


const CurrentWeather = ({
  current,
  temperature,
  loading,
  error,
  formatNumber,
  formatDate,
  getWeatherIcon,
}: CurrentWeatherProps) => {
  if (loading) {
    return (
      <Typography color="text.secondary">
        Loading current weather...
      </Typography>
    );
  }

  if (error || !current) {
    return (
      <Typography color="text.secondary">
        No current weather data is
        available for this entity.
      </Typography>
    );
  }


  const items = [
    {
      label: "Condition",
      value:
        current.condition,
      icon:
        getWeatherIcon(
          current.condition
        ),
    },
    {
      label: "High / Low",
      value: `${formatNumber(
        current.tempMax
      )} °C / ${formatNumber(
        current.tempMin
      )} °C`,
      icon:
        <ThermostatRounded />,
    },
    {
      label: "Rainfall",
      value: `${formatNumber(
        current.rainfall
      )} mm`,
      icon:
        <OpacityRounded />,
    },
    {
      label: "Cloud Cover",
      value: `${formatNumber(
        current.cloudCover,
        0
      )}%`,
      icon:
        <CloudRounded />,
    },
    {
      label: "Humidity",
      value: `${formatNumber(
        current.humidity,
        0
      )}%`,
      icon:
        <WaterDropRounded />,
    },
    {
      label: "Wind Speed",
      value: `${formatNumber(
        current.windSpeed
      )} km/h`,
      icon:
        <AirRounded />,
    },
    {
      label: "UV Index",
      value:
        formatNumber(
          current.uvIndex
        ),
      icon:
        <WbSunnyRounded />,
    },
    {
      label: "Sunshine",
      value: `${formatNumber(
        current.sunshine
      )} hrs`,
      icon:
        <WbSunnyRounded />,
    },
  ];


  return (
    <Box>
      <Stack
        direction={{
          xs: "column",
          md: "row",
        }}
        spacing={2}
        justifyContent="space-between"
        mb={3}
      >
        <Box>
          <Typography
            variant="h6"
            fontWeight={800}
            color="text.primary"
          >
            Current Conditions
          </Typography>

          <Typography
            color="text.secondary"
          >
            Latest available observation:
            {" "}
            {formatDate(
              current.date
            )}
          </Typography>
        </Box>

        <Stack
          direction="row"
          spacing={1.5}
          alignItems="center"
        >
          <Box
            sx={{
              px: 2,
              py: 1.25,
              bgcolor:
                "#EEF4FF",
              borderRadius: 2.5,
              color:
                "text.primary",
              fontWeight: 800,
            }}
          >
            {temperature !== null
              ? `${formatNumber(
                temperature
              )} °C`
              : "—"}
          </Box>

          <Box
            sx={{
              px: 2,
              py: 1.25,
              bgcolor:
                "#F5F6F8",
              borderRadius: 2.5,
              color:
                "#68758A",
              fontWeight: 700,
            }}
          >
            {current.condition}
          </Box>
        </Stack>
      </Stack>


      <Box
        sx={{
          display: "grid",
          gridTemplateColumns: {
            xs:
              "repeat(1, minmax(0, 1fr))",
            sm:
              "repeat(2, minmax(0, 1fr))",
          },
          gap: 1.5,
        }}
      >
        {items.map(
          (item) => (
            <WeatherMetric
              key={
                item.label
              }
              label={
                item.label
              }
              value={
                item.value
              }
              icon={
                item.icon
              }
            />
          )
        )}
      </Box>
    </Box>
  );
};


/* =========================================================
   WEATHER OUTLOOK
========================================================= */


interface WeatherOutlookGridProps {
  records:
  WeatherOutlookDay[];

  formatNumber: (
    value:
      | number
      | null
      | undefined,
    decimals?: number
  ) => string;

  formatDate: (
    value: string
  ) => string;

  getDayName: (
    value: string
  ) => string;

  getWeatherIcon: (
    condition:
      | string
      | null
      | undefined
